/** Real same-entity ownership transfers, preserved inventories and safe refusal before any cut. */
public final class VehicleCouplingRuntimeChecks {
    private static int checks;
    private static void require(boolean ok,String message){checks++;if(!ok)throw new IllegalStateException("Vehicle coupling: "+message);}
    public static final class Fixture implements AutoCloseable {
        public final WorldServer world;public final EntityPlayerMP actor;public final BlockPos base,moduleHead,chest;public final EntityGroundVehicle craft;public final BlockPos head;
        public Fixture(WorldServer world,EntityPlayerMP actor,BlockPos base)throws Exception{
            this.world=world;this.actor=actor;this.base=base;clear(world,base);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunkFromChunkCoords((base.getX()>>4)+x,(base.getZ()>>4)+z);
            actor.setPositionAndUpdate(base.getX()+1,base.getY()+5,base.getZ()+5);Block thruster=Block.getBlockFromName("vandorlabs:impulse_engine"),coupler=Block.getBlockFromName("vandorlabs:square_coupler");
            for(int x=0;x<3;x++){world.setBlockState(base.east(x),thruster.getDefaultState().withProperty(BlockPropulsionLight.FACING,EnumFacing.DOWN),2);world.setBlockState(base.east(x).up(),Blocks.IRON_BLOCK.getDefaultState(),2);}
            Block lift=null;for(Block candidate:Block.REGISTRY)if(VehicleFlight.lift(candidate)){lift=candidate;break;}require(lift!=null,"registered lift fixture");for(int index=0;index<3;index++)world.setBlockState(base.add(index,1,1),lift.getDefaultState().withProperty(BlockPropulsionLight.FACING,EnumFacing.DOWN),2);
            BlockPos seat=base.up(2);world.setBlockState(seat,ModBlocks.PILOT_SEAT.getDefaultState(),2);ModBlocks.PILOT_SEAT.onBlockPlacedBy(world,seat,world.getBlockState(seat),actor,new ItemStack(ModBlocks.PILOT_SEAT));world.setBlockState(base.east().up(2),ModBlocks.VEHICLE_CONTROLLER.getDefaultState(),2);
            BlockPos at=base.add(3,1,0);world.setBlockState(at,coupler.getDefaultState().withProperty(BlockCoupler.FACING,EnumFacing.EAST),2);((TileCoupler)world.getTileEntity(at)).authorize(actor);
            VehicleScan scan=new VehicleScan(world,seat);while(!scan.step(1024)){}require(scan.result!=null,"complete native core fixture "+scan.error);head=at.subtract(scan.origin);craft=new EntityGroundVehicle(world);craft.install(scan.result);craft.recordCouplingActor(actor);craft.setPosition(scan.origin.getX(),scan.origin.getY(),scan.origin.getZ());CopyWorldBridge.remove(world,scan.result,scan.origin);craft.transferEpoch=VehicleOwnership.update(world,craft.getUniqueID(),1,true);require(world.spawnEntity(craft),"actual vehicle entity spawn");
            moduleHead=base.add(4,1,0);chest=moduleHead.east();world.setBlockState(moduleHead,coupler.getDefaultState().withProperty(BlockCoupler.FACING,EnumFacing.WEST),2);TileCoupler other=(TileCoupler)world.getTileEntity(moduleHead);other.authorize(actor);other.configure(ChannelList.EMPTY,true);world.setBlockState(chest,Blocks.CHEST.getDefaultState(),2);((TileEntityChest)world.getTileEntity(chest)).setCustomName("Coupled cargo");((TileEntityChest)world.getTileEntity(chest)).setInventorySlotContents(0,new ItemStack(Items.DIAMOND,7));
            head().configure(ChannelList.EMPTY,true);craft.signals.persist();
        }
        public TileCoupler head(){return (TileCoupler)craft.view.getTileEntity(head);}
        public VehicleCouplingPlan attachPlan()throws Exception{craft.signals.persist();VehicleCouplingPlan.Alignment alignment=new VehicleCouplingPlan.Alignment(craft,craft.structure);Set<BlockPos> exclude=new HashSet<>();for(VehicleStructure.Cell cell:craft.structure.cells)exclude.add(alignment.worldCell(craft.structure,cell.pos));VehicleScan scan=VehicleScan.attachment(world,moduleHead,exclude);while(!scan.step(1024)){}require(scan.result!=null,"whole module scan "+scan.error);return VehicleCouplingPlan.attach(craft,actor,head,scan);}
        public VehicleCouplingPlan detachPlan()throws Exception{head().configure(ChannelList.EMPTY,false);craft.signals.persist();List<VehicleStructure.Cell> cells=new ArrayList<>();for(VehicleStructure.Cell cell:craft.structure.cells){IBlockState state=cell.state;if(state.getBlock() instanceof BlockCoupler){TileCoupler tile=(TileCoupler)craft.view.getTileEntity(cell.pos);state=state.withProperty(BlockCoupler.LOCKED,tile.requested());}cells.add(new VehicleStructure.Cell(cell.pos,state,cell.tileData()));}VehicleStructure proposed=new VehicleStructure(cells,craft.structure.seat,craft.structure.facing,craft.structure.gearCount);VehicleWorld view=new VehicleWorld(world,proposed);VehicleScan scan=VehicleScan.attachment(view,craft.structure.controller().pos,Collections.emptySet());while(!scan.step(1024)){}require(scan.result!=null,"retained component scan "+scan.error);return VehicleCouplingPlan.detach(craft,actor,head,proposed,scan);}
        public void submit(VehicleCouplingPlan plan)throws Exception{List<Exception> failed=new ArrayList<>();VehicleCouplingTransfer.submit(actor,plan,()->{},failed::add);VehicleCouplingTransfer.drainForChecks(world);if(!failed.isEmpty())throw failed.get(0);require(!VehicleCouplingTransfer.busy(craft),"queued change passed its verified checkpoint");}
        public void close(){if(VehicleCouplingTransfer.pendingCount(world)==0){craft.signals.close();craft.setDead();world.removeEntityDangerously(craft);try{VehicleOwnership.update(world,craft.getUniqueID(),craft.transferEpoch+1,false);}catch(java.io.IOException failure){throw new IllegalStateException("Fixture vehicle ownership cleanup failed",failure);}clear(world,base);}}
    }
    private static final class CopyWorldBridge{static void remove(WorldServer world,VehicleStructure snapshot,BlockPos origin){com.vandorlabs.copier.CopyWorld.clear(world,snapshot,origin);}}
    public static void run(WorldServer world,EntityPlayerMP actor)throws Exception{
        checks=0;BlockPos base=new BlockPos(860,150,300);double x=actor.posX,y=actor.posY,z=actor.posZ;
        try{for(boolean hover:new boolean[]{false,true})try(Fixture f=new Fixture(world,actor,base)){
            require(!hover||f.craft.setHover(true),"Hover fixture has three lift blocks");if(!hover){f.head().configure(ChannelList.EMPTY,false);f.craft.signals.persist();List<VehicleStructure.Cell> controls=new ArrayList<>(f.craft.structure.cells);controls.add(new VehicleStructure.Cell(new BlockPos(2,2,0),Blocks.IRON_BLOCK.getDefaultState(),null));controls.add(new VehicleStructure.Cell(new BlockPos(3,2,0),Blocks.LEVER.getDefaultState().withProperty(net.minecraft.block.BlockLever.FACING,net.minecraft.block.BlockLever.EnumOrientation.EAST).withProperty(net.minecraft.block.BlockLever.POWERED,true),null));VehicleStructureEdits.install(f.craft,controls,"Local physical coupler input fixture");require(!f.head().requested(),"unsampled carried physical input starts inactive");}
            if(!hover)authorizationProof(f);UUID id=f.craft.getUniqueID();int original=f.craft.structure.cells.size();TileEntityChest originalChest=(TileEntityChest)world.getTileEntity(f.chest);NBTTagCompound source=originalChest.writeToNBT(new NBTTagCompound());
            for(int i=0;i<100&&!world.isAirBlock(f.chest);i++){VehicleCouplings.tick(world);VehicleCouplingTransfer.tick(world);}VehicleCouplingTransfer.drainForChecks(world);require(world.isAirBlock(f.chest)&&f.craft.structure.cells.size()==original+2,"activated opposing heads automatically scan and add world section");require(f.craft.getUniqueID().equals(id)&&!f.craft.isDead,"attachment preserves existing vehicle UUID");require(originalChest.isEmpty(),"removed world chest stale inventory reference is inert");BlockPos local=f.chest.subtract(base);TileEntityChest carried=(TileEntityChest)f.craft.view.getTileEntity(local);require(carried!=null&&carried.getStackInSlot(0).getCount()==7&&carried.getName().equals("Coupled cargo"),"attached chest preserves exact inventory and name");
            // A released pair may still share one entity through another hull connection.
            List<VehicleStructure.Cell> released=new ArrayList<>();for(VehicleStructure.Cell cell:f.craft.structure.cells)released.add(cell.state.getBlock() instanceof BlockCoupler?new VehicleStructure.Cell(cell.pos,cell.state.withProperty(BlockCoupler.LOCKED,false),cell.tileData()):cell);f.craft.updateCanopies(new VehicleStructure(released,f.craft.structure.seat,f.craft.structure.facing,f.craft.structure.gearCount),true);for(net.minecraft.tileentity.TileEntity raw:new ArrayList<>(f.craft.view.tiles.values()))if(raw instanceof TileCoupler){((TileCoupler)raw).sample();require(((TileCoupler)raw).connected(),"active same-entity heads re-latch immediately");}
            f.craft.rotationYaw=30;if(hover)f.head().configure(ChannelList.EMPTY,false);else{List<VehicleStructure.Cell> controls=new ArrayList<>();for(VehicleStructure.Cell cell:f.craft.structure.cells)controls.add(cell.state.getBlock()==Blocks.LEVER?new VehicleStructure.Cell(cell.pos,cell.state.withProperty(net.minecraft.block.BlockLever.POWERED,false),cell.tileData()):cell);f.craft.updateCanopies(new VehicleStructure(controls,f.craft.structure.seat,f.craft.structure.facing,f.craft.structure.gearCount),true);VehicleCouplings.wake(f.craft);}for(int i=0;i<100;i++)VehicleCouplings.tick(world);require(f.craft.structure.cells.size()==original+2&&world.isAirBlock(f.chest)&&f.head().connected()&&!f.head().requested(),"unsafe heading keeps whole section physically attached after real input deactivation");
            f.craft.rotationYaw=0;world.setBlockState(f.chest,Blocks.OBSIDIAN.getDefaultState(),2);VehicleCouplings.wake(f.craft);for(int i=0;i<100;i++)VehicleCouplings.tick(world);require(f.craft.structure.cells.size()==original+2&&f.head().connected()&&world.getBlockState(f.chest).getBlock()==Blocks.OBSIDIAN,"obstruction refuses detach without changing either owner");world.setBlockToAir(f.chest);VehicleCouplings.wake(f.craft);
            for(int i=0;i<100&&world.isAirBlock(f.chest);i++){VehicleCouplings.tick(world);VehicleCouplingTransfer.tick(world);}VehicleCouplingTransfer.drainForChecks(world);require(f.craft.structure.cells.size()==original&&f.craft.getUniqueID().equals(id),"safe release removes only module from same entity");TileEntityChest restored=(TileEntityChest)world.getTileEntity(f.chest);require(restored!=null&&restored.getStackInSlot(0).getCount()==7&&restored.getName().equals("Coupled cargo"),"safe detach materializes exact original cargo once");
        }alignmentMatrix(world,actor,base);}finally{actor.setPositionAndUpdate(x,y,z);}
        System.out.println("[vandorlabs][reprolab] dynamic-vehicle-coupling PASS checks="+checks+" actual world-section autoscan attach same UUID/inventory stale-reference inertness unsafe heading/obstruction keepattached safe world detach");
    }
    private static void authorizationProof(Fixture fixture){
        UUID victim=UUID.randomUUID();TileCoupler tile=fixture.head();NBTTagCompound copied=tile.writeToNBT(new NBTTagCompound());copied.setUniqueId("CouplerActor",victim);tile.readFromNBT(copied);tile.markDirty();fixture.craft.signals.persist();
        require(tile.operator().equals(victim),"copied portable tile retains its creator data exactly");require(VehicleCouplings.authorizer(fixture.craft)==fixture.actor,"actual assembly receipt takes precedence over a copied victim tile UUID");
        NBTTagCompound entity=fixture.craft.writeToNBT(new NBTTagCompound());EntityGroundVehicle restored=new EntityGroundVehicle(fixture.world);restored.readFromNBT(entity);require(fixture.actor.getUniqueID().equals(restored.couplingActor()),"entity authorizer survives entity save separately from block snapshots");require(restored.structure.at(fixture.head).tileData().getUniqueId("CouplerActor").equals(victim),"entity save keeps portable historical data distinct from authorization");restored.signals.close();
        fixture.craft.couplingActor=null;boolean denied=false;try{VehicleCouplings.authorizer(fixture.craft);}catch(IllegalArgumentException expected){denied=true;}require(denied,"legacy or copied tiles cannot manufacture an entity authorization receipt");fixture.craft.authorizeCouplingGui(fixture.actor,fixture.head());require(VehicleCouplings.authorizer(fixture.craft)==fixture.actor,"actual authorized carried dialog grants a fresh entity receipt");
        double x=fixture.actor.posX,y=fixture.actor.posY,z=fixture.actor.posZ;boolean taxi=VehicleTaxiMode.enabled(fixture.craft.structure);if(taxi)VehicleTaxiMode.apply(fixture.craft,false);fixture.craft.couplingActor=victim;fixture.craft.assignSeat(fixture.actor,fixture.craft.structure.seat);require(fixture.actor.startRiding(fixture.craft,true),"actual driver boards a vehicle with another assembler's receipt");require(fixture.actor.getUniqueID().equals(fixture.craft.couplingActor()),"actual controlling driver replaces historical assembler authority immediately");fixture.actor.dismountRidingEntity();require(fixture.actor.getUniqueID().equals(fixture.craft.couplingActor())&&VehicleCouplings.authorizer(fixture.craft)==fixture.actor,"last actual driver remains authorizer after leaving; victim privileges do not return");if(taxi)VehicleTaxiMode.apply(fixture.craft,true);fixture.actor.setPositionAndUpdate(x,y,z);
    }
    private static void alignmentMatrix(WorldServer world,EntityPlayerMP actor,BlockPos base)throws Exception{
        List<EnumFacing> faces=new ArrayList<>(Arrays.asList(EnumFacing.values()));for(int i=0;i<3;i++)faces.add(EnumFacing.EAST);int trial=0;
        for(EnumFacing face:faces)try(Fixture f=new Fixture(world,actor,base)){
            world.removeTileEntity(f.chest);world.setBlockToAir(f.chest);world.removeTileEntity(f.moduleHead);world.setBlockToAir(f.moduleHead);List<VehicleStructure.Cell> cells=new ArrayList<>();VehicleStructure.Cell old=f.craft.structure.at(f.head);for(VehicleStructure.Cell cell:f.craft.structure.cells)if(!cell.pos.equals(f.head))cells.add(cell);
            BlockPos head;switch(face){case WEST:head=new BlockPos(-1,1,0);break;case NORTH:head=new BlockPos(1,1,-1);break;case SOUTH:head=new BlockPos(2,2,1);cells.add(new VehicleStructure.Cell(new BlockPos(2,2,0),Blocks.IRON_BLOCK.getDefaultState(),null));break;case UP:head=new BlockPos(2,2,0);break;case DOWN:head=new BlockPos(1,0,-1);cells.add(new VehicleStructure.Cell(new BlockPos(1,1,-1),Blocks.IRON_BLOCK.getDefaultState(),null));break;default:head=f.head;}
            NBTTagCompound data=VehicleTileData.translated(old.tileData(),head.subtract(f.head));cells.add(new VehicleStructure.Cell(head,old.state.withProperty(BlockCoupler.FACING,face),data));BlockPos oldSeat=f.craft.structure.seat;VehicleStructureEdits.install(f.craft,cells,"Coupler orientation fixture");head=head.add(f.craft.structure.seat.subtract(oldSeat));if(trial>=6)f.craft.rotationYaw=(trial-5)*90;
            VehicleCouplingPlan.Alignment alignment=new VehicleCouplingPlan.Alignment(f.craft,f.craft.structure);BlockPos placed=VehicleRotation.cell(head,(int)f.craft.structure.bounds.maxX,(int)f.craft.structure.bounds.maxZ,alignment.turns);EnumFacing worldFace=alignment.placed.at(placed).state.getValue(BlockCoupler.FACING);BlockPos module=alignment.origin.add(placed).offset(worldFace),chest=module.offset(worldFace);Block coupler=Block.getBlockFromName("vandorlabs:square_coupler");world.setBlockState(module,coupler.getDefaultState().withProperty(BlockCoupler.FACING,worldFace.getOpposite()),2);TileCoupler source=(TileCoupler)world.getTileEntity(module);source.authorize(actor);source.configure(ChannelList.EMPTY,true);world.setBlockState(chest,Blocks.CHEST.getDefaultState(),2);((TileEntityChest)world.getTileEntity(chest)).setInventorySlotContents(0,new ItemStack(Items.EMERALD,9));
            Set<BlockPos> excluded=new HashSet<>();for(VehicleStructure.Cell cell:f.craft.structure.cells)excluded.add(alignment.worldCell(f.craft.structure,cell.pos));VehicleScan scan=VehicleScan.attachment(world,module,excluded);while(!scan.step(1024)){}require(scan.result!=null,"oriented source scan "+face+"/"+alignment.turns+": "+scan.error);VehicleCouplingPlan plan=VehicleCouplingPlan.attach(f.craft,actor,head,scan);VehiclePose newPose=new VehiclePose(plan.x,plan.y,plan.z,f.craft.rotationYaw);BlockPos shift=plan.after.seat.subtract(plan.before.seat);
            for(VehicleStructure.Cell cell:plan.before.cells){net.minecraft.util.math.Vec3d point=new net.minecraft.util.math.Vec3d(cell.pos).addVector(.5,.5,.5);require(f.craft.toWorld(point).squareDistanceTo(newPose.world(point.addVector(shift.getX(),shift.getY(),shift.getZ()),plan.after.bounds.maxX/2,plan.after.bounds.maxZ/2))<1e-12,"rebase retains original cell worldpose");}
            f.submit(plan);boolean found=false;for(VehicleStructure.Cell cell:f.craft.structure.cells)if(cell.state.getBlock()==Blocks.CHEST){TileEntityChest cargo=(TileEntityChest)f.craft.view.getTileEntity(cell.pos);require(cargo.getStackInSlot(0).getItem()==Items.EMERALD&&cargo.getStackInSlot(0).getCount()==9,"oriented merge preserves inventory");require(f.craft.toWorld(new net.minecraft.util.math.Vec3d(cell.pos).addVector(.5,.5,.5)).squareDistanceTo(new net.minecraft.util.math.Vec3d(chest).addVector(.5,.5,.5))<1e-10,"oriented merge preserves exact cargo worldplacement");found=true;}require(found&&world.isAirBlock(chest),"actual oriented merge has one cargo owner "+face+alignment.turns);trial++;
        }
        Block full=Block.getBlockFromName("vandorlabs:square_coupler"),slab=Block.getBlockFromName("vandorlabs:vehicle_coupler_slab");IBlockState low=slab.getDefaultState().withProperty(BlockCoupler.FACING,EnumFacing.EAST),high=low.withProperty(BlockCouplerSlab.HALF,net.minecraft.block.BlockSlab.EnumBlockHalf.TOP);require(VehicleCouplings.matching(low,low.withProperty(BlockCoupler.FACING,EnumFacing.WEST)),"matching slab halves mate");require(!VehicleCouplings.matching(low,high.withProperty(BlockCoupler.FACING,EnumFacing.WEST))&&!VehicleCouplings.matching(full.getDefaultState().withProperty(BlockCoupler.FACING,EnumFacing.WEST),low),"slab height and full/slab mismatch refused");
        System.out.println("[vandorlabs][reprolab] coupling-orientation-matrix PASS actual transfers="+trial+" six full mount faces four vehicle headings exact original/cargo worldpose and inventory; slab matching heights");
    }
    private static void clear(WorldServer world,BlockPos base){for(BlockPos cursor:BlockPos.getAllInBox(base.add(-3,-2,-3),base.add(12,7,5))){BlockPos at=cursor.toImmutable();world.removeTileEntity(at);world.setBlockToAir(at);}}
    private VehicleCouplingRuntimeChecks(){}
}
